<template>
  <div class="app-container">
    <!-- 顶部标题和清除按钮 -->
    <div class="header">
      <h1>人工智能技术岗面试官与虚拟人交互系统</h1>
      <button id="clearBtn" @click="clearChatHistory" class="clear-btn">
        清除历史聊天记录
      </button>
    </div>

    <!-- 主内容区 -->
    <el-container class="main-content">
      <!-- 左侧虚拟人控制区 -->
      <el-aside width="300px" class="virtual-aside">
        <el-row>
          <el-button v-if="!avatarPlatform" @click="initSDK()" type="primary">
            实例化虚拟人SDK
          </el-button>

          <el-button v-if="avatarPlatform" @click="createRecoder()" type="primary">
            创建录音器
          </el-button>

          <el-button v-if="avatarPlatform" @click="setSDKEvenet()" type="primary">
            设置SDK监听事件
          </el-button>

          <el-button v-if="avatarPlatform" @click="setPlayerEvenet()" type="primary">
            设置播放器监听事件
          </el-button>

          <el-button v-if="!isSDKInitialized" @click="SetApiInfodialog = true" type="primary">
            设置API信息
          </el-button>

          <el-button v-if="avatarPlatform" @click="SetGlobalParamsdialog = true" type="primary">
            设置全局参数
          </el-button>

          <el-button v-if="avatarPlatform && !isRecording" @click="startRecord()" type="primary">
            开启录音
          </el-button>

          <el-button v-if="avatarPlatform && isRecording" @click="stopRecord()" type="primary">
            关闭录音
          </el-button>

          <el-button v-if="!isSDKInitialized || !avatarPlatform" @click="startInterview()" type="primary">
            开始面试（自动初始化）
          </el-button>

          <el-button v-if="avatarPlatform" @click="destroySDK()" type="primary">
            销毁SDK
          </el-button>
        </el-row>

        <!-- 语音分析指标 -->
        <div class="audio-analysis-container">
          <h3>语音实时分析指标</h3>
          <div class="metrics">
            <div class="metric-card">
              <div class="metric-title">音量</div>
              <div class="metric-value">{{ volume.toFixed(1) }} dB</div>
              <div class="volume-graph">
                <div class="volume-bar" :style="{ width: volumePercent + '%' }"></div>
              </div>
            </div>
            <div class="metric-card">
              <div class="metric-title">音调稳定度</div>
              <div class="metric-value">{{ pitchStability.toFixed(1) }}%</div>
              <div class="metric-progress">
                <div class="progress-bar" :style="{ width: pitchStability + '%' }"></div>
              </div>
            </div>
            <div class="metric-card">
              <div class="metric-title">音调</div>
              <div class="metric-value">{{ pitch.toFixed(1) }} Hz</div>
              <div class="pitch-graph">
                <div class="pitch-point" :style="{ left: pitchPosition + '%' }"></div>
              </div>
            </div>
          </div>
          <div class="frequency-chart">
            <canvas ref="frequencyCanvas"></canvas>
          </div>
        </div>
      </el-aside>

      <!-- 右侧聊天区和虚拟人显示区 -->
      <el-main class="chat-and-avatar">
        <!-- 虚拟人显示 -->
        <div class="avatar-display" id="wrapper"
          style="position: relative; width: 400px; height: 400px; margin: 20px auto;">
          <video ref="video" autoplay muted class="avatar-video"></video>
          <div class="status avatar-status" :textContent="status"></div>
        </div>

        <!-- 聊天内容区域 -->
        <div id="chat-container">
          <div id="results" class="chat-results">
            <div id="result">
              <div v-for="(message, index) in chatMessages.filter(m => m.role !== 'system')" :key="index"
                :class="['message', `${message.role}-message`]">
                <img class="avatar" :src="message.role === 'user' ? 'redrun.avif' : 'spark.png'"
                  :alt="`${message.role} avatar`" />
                <div class="content" v-html="parseContent(message.content)"></div>
              </div>
            </div>
          </div>

          <!-- 文字输入区域 -->
          <div id="sendVal" class="chat-input">
            <input id="question" type="text" placeholder="请输入信息..." v-model="userInput" @keydown.enter="sendMessage"
              :disabled="isLoading || isRecording || isInitializing" />
            <button id="btn" @click="sendMessage"
              :disabled="isLoading || !userInput.trim() || isRecording || isInitializing">
              {{ isLoading ? '发送中...' : '发送' }}
            </button>
          </div>

          <!-- 语音转写结果 -->
          <div class="transcription-result">
            <h4>语音转写结果</h4>
            <p>{{ transcriptionResult || '等待转写...' }}</p>
          </div>
        </div>
      </el-main>
    </el-container>

    <!-- 设置API信息对话框 -->
    <el-dialog title="设置API信息" :visible.sync="SetApiInfodialog">
      <el-form :model="form">
        <el-form-item label="AppID">
          <el-input v-model="form.appid" placeholder="请输入AppID"></el-input>
        </el-form-item>
        <el-form-item label="ApiKey">
          <el-input v-model="form.apikey" placeholder="请输入ApiKey"></el-input>
        </el-form-item>
        <el-form-item label="ApiSecret">
          <el-input v-model="form.apisecret" placeholder="请输入ApiSecret"></el-input>
        </el-form-item>
        <el-form-item label="SceneID">
          <el-input v-model="form.sceneid" placeholder="请输入SceneID"></el-input>
        </el-form-item>
        <el-form-item label="ServerUrl">
          <el-input v-model="form.serverurl" placeholder="请输入ServerUrl"></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="SetApiInfodialog = false">取消</el-button>
        <el-button type="primary" @click="(SetApiInfodialog = false, setApiInfo())">确定</el-button>
      </div>
    </el-dialog>

    <!-- 设置全局参数对话框 -->
    <el-dialog title="设置全局参数" :visible.sync="SetGlobalParamsdialog">
      <el-form :model="setglobalparamsform">
        <el-form-item label="形象ID">
          <el-input v-model="setglobalparamsform.avatar.avatar_id" placeholder="请输入形象ID"></el-input>
        </el-form-item>
        <el-form-item label="发音人">
          <el-input v-model="setglobalparamsform.tts.vcn" placeholder="请输入发音人ID"></el-input>
        </el-form-item>
        <el-form-item label="视频协议">
          <el-select v-model="setglobalparamsform.stream.protocol" placeholder="请选择视频协议">
            <el-option label="xrtc" value="xrtc"></el-option>
            <el-option label="webrtc" value="webrtc"></el-option>
            <el-option label="rtmp" value="rtmp"></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="SetGlobalParamsdialog = false">取消</el-button>
        <el-button type="primary" @click="(SetGlobalParamsdialog = false, setGlobalParams())">确定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import AvatarPlatform, { PlayerEvents, SDKEvents } from "../vm-sdk/avatar-sdk-web_3.1.1.1011/index.js";
import axios from "axios";
import "element-ui/lib/theme-chalk/index.css";

export default {
  name: "AIInterviewSystem",
  data() {
    return {
      // AI聊天功能数据
      userInput: '',
      chatMessages: [],
      isLoading: false,
      selectedModel: '4.0Ultra',
      models: {
        'lite': {
          domain: 'lite',
          url: 'wss://spark-api.xf-yun.com/v1.1/chat',
          maxTokens: 4096
        },
        'generalv3': {
          domain: 'generalv3',
          url: 'wss://spark-api.xf-yun.com/v3.1/chat',
          maxTokens: 8192
        },
        'pro-128k': {
          domain: 'pro-128k',
          url: 'wss://spark-api.xf-yun.com/chat/pro-128k',
          maxTokens: 4096
        },
        'generalv3.5': {
          domain: 'generalv3.5',
          url: 'wss://spark-api.xf-yun.com/v3.5/chat',
          maxTokens: 8192
        },
        'max-32k': {
          domain: 'max-32k',
          url: 'wss://spark-api.xf-yun.com/chat/max-32k',
          maxTokens: 8192
        },
        '4.0Ultra': {
          domain: '4.0Ultra',
          url: 'wss://spark-api.xf-yun.com/v4.0/chat',
          maxTokens: 8192
        },
        'kjwx': {
          domain: 'kjwx',
          url: 'wss://spark-openapi-n.cn-huabei-1.xf-yun.com/v1.1/chat_kjwx',
          maxTokens: 8192
        }
      },

      // 虚拟人功能数据
      avatarPlatform: null,
      recorder: null, // 定义recorder变量
      isSDKInitialized: true, // 初始化为false，连接成功后设为true
      SetApiInfodialog: false,
      SetGlobalParamsdialog: false,
      form: {
        appid: "afaaafc3",
        apikey: "043c90016ad15525894a7a8cc3ce09dc",
        apisecret: "ODZmMDA3MGIwOTkxNDNiNmQ4NjMyMzA1",
        sceneid: "193572571395002368",
        serverurl: "wss://avatar.cn-huadong-1.xf-yun.com/v1/interact"
      },
      setglobalparamsform: {
        stream: {
          protocol: "xrtc",
          fps: 25,
          bitrate: 1000000,
          alpha: false
        },
        avatar: {
          avatar_id: "110017006",
          width: 1080,
          height: 1920,
          mask_region: "[0,0,1080,1920]",
          scale: 1,
          move_h: 0,
          move_v: 0,
          audio_format: 1
        },
        tts: {
          vcn: "x4_mingge",
          speed: 50,
          pitch: 50,
          volume: 100, // 确保音量不为0
          emotion: 13
        },
        avatar_dispatch: {
          interactive_mode: 1
        },
        subtitle: {
          subtitle: 1,
          font_color: "#FFFFFF",
          font_name: "Sanji.Suxian.Simple",
          position_x: 100,
          position_y: 0,
          font_size: 10,
          width: 100,
          height: 100
        },
        enable: false,
        background: {
          type: "res_key",
          data: ""
        }
      },
      formLabelWidth: "120px",

      // 录音和语音转写数据
      isRecording: false,
      mediaRecorder: null,
      audioChunks: [],
      transcriptionResult: null,

      // 语音分析数据
      isAnalyzing: false,
      audioContext: null,
      analyser: null,
      microphone: null,
      scriptProcessor: null,
      animationFrameId: null,
      volume: 0,
      pitch: 0,
      pitchStability: 50,
      pitchHistory: [],
      frequencyData: new Float32Array(1024),
      byteFrequencyData: new Uint8Array(1024),
      volumePercent: 0, // 定义volumePercent变量
      pitchPosition: 0, // 定义pitchPosition变量

      // 摄像头和表情识别数据
      mediaStream: null,
      status: "等待初始化...",
      answer: "",
      isProcessing: false,

      // 初始化状态标记
      isInitializing: false,
      // 错误信息存储
      initError: ''
    };
  },
  mounted() {
    this.initChatHistory();
    this.initVoiceAnalysis();
    this.initCamera();
  },
  beforeDestroy() {
    this.stopRecording();
    this.stopVoiceAnalysis();
    if (this.avatarPlatform) {
      this.avatarPlatform.destroy();
      this.avatarPlatform = null;
    }
  },
  methods: {
    // AI聊天功能方法
    initChatHistory() {
      let chatHistory = localStorage.getItem('chatHistory');
      if (chatHistory) {
        this.chatMessages = JSON.parse(chatHistory).map(item => {
          if (item.content.startsWith("data:image/")) {
            item.content = "已经为您生成图片"
          }
          return item
        });
      } else {
        this.chatMessages = [
          {
            role: 'system',
            content: `你是一位经验丰富的人工智能技术岗面试官，但也可以灵活切换到其他领域的交流。
    - 主要职责：提问技术问题，评估候选人水平
    - 扩展功能：当用户明确提出其他需求时，可切换到相关话题（如行业趋势、学习资源等）
    - 回答风格：保持专业，但允许一定的灵活性和幽默感
    - 注意事项: 无论用户说什么，都要回复，不能什么都不回复`
          },
          {
            role: 'assistant',
            content: `你好，${localStorage.getItem('username') || '游客'}！我是你的人工智能技术岗面试官。`
          }
        ];
      }
      this.scrollToBottom();
    },

    clearChatHistory() {
      const isClear = window.confirm("确定要清除所有聊天记录吗？此操作不可撤销。");
      if (isClear) {
        localStorage.removeItem('chatHistory');
        this.chatMessages = [];
        this.initChatHistory();
      }
    },

    saveChatHistory() {
      localStorage.setItem('chatHistory', JSON.stringify(this.chatMessages));
    },

    async sendMessage() {
      const inputVal = this.userInput.trim();
      if (!inputVal || this.isRecording || this.isInitializing) return;

      this.isLoading = true;

      // 保存用户消息
      const userMessage = {
        role: 'user',
        content: inputVal
      };

      this.chatMessages.push(userMessage);
      this.saveChatHistory();
      this.userInput = '';
      this.scrollToBottom();

      // 创建助手消息
      const assistantMessage = {
        role: 'assistant',
        content: '<div class="loading-dots"><div></div><div></div><div></div></div>'
      };

      this.chatMessages.push(assistantMessage);
      this.saveChatHistory();
      this.scrollToBottom();

      try {
        // 获取当前选中模型的配置
        const modelConfig = this.models[this.selectedModel];

        // 获取连接URL并建立WebSocket连接
        const url = await this.getWebsocketUrl(modelConfig.url);
        console.log("生成的WebSocket URL:", url);

        const ws = new WebSocket(url);

        // 等待连接建立
        await new Promise((resolve, reject) => {
          ws.addEventListener('open', (event) => {
            console.log('开启连接！！', event);
            resolve(event);
          });
          ws.addEventListener('error', (error) => {
            console.log('连接发送错误！！', error);
            reject(error);
          });
        });

        // 准备发送给服务器的参数
        const params = this.getParams(this.chatMessages);
        console.log("发送的参数:", params);
        let answer = "";

        ws.send(JSON.stringify(params));

        ws.addEventListener("message", async (event) => {
          try {
            const data = JSON.parse(event.data);
            console.log("收到消息:", data);

            if (data.header.code !== 0) {
              console.error("Error:", data.header.message);
              answer = `抱歉，出现错误: ${data.header.message}`;
              this.updateAssistantMessage(answer);
              ws.close();
              return;
            }

            if (data.payload.choices.text) {
              answer += data.payload.choices.text[0].content;
              // 移除加载动画并更新内容
              this.updateAssistantMessage(answer);
              this.scrollToBottom();

              // 如果虚拟人已初始化且连接成功，将回答发送给虚拟人
              if (this.avatarPlatform && this.isSDKInitialized) {
                this.sendToAvatar(answer); // 使用封装的方法发送文本
              }
            }

            if (data.header.status === 2) {
              // 处理函数调用
              const functionCall = data?.payload?.choices?.text[0]?.function_call;
              if (functionCall) {
                const name = functionCall.name;
                const params = JSON.parse(functionCall.arguments);
                const target = this.getFunctionByName(name);

                if (target) {
                  // 显示正在处理函数的提示
                  this.updateAssistantMessage(`${answer}<br><br><i>正在处理 ${name} 请求...</i>`);
                  this.scrollToBottom();

                  try {
                    const res = await target(name, params); // 直接调用函数
                    answer = res;
                  } catch (error) {
                    answer = `处理 ${name} 请求时出错: ${error.message}`;
                  }
                }
              }

              // 保存最终回答
              this.chatMessages[this.chatMessages.length - 1].content = answer;
              this.saveChatHistory();
              this.updateAssistantMessage(answer);
              this.scrollToBottom();

              // 如果虚拟人已初始化且连接成功，将最终回答发送给虚拟人
              if (this.avatarPlatform && this.isSDKInitialized) {
                this.sendToAvatar(answer); // 使用封装的方法发送文本
              }

              setTimeout(() => {
                ws.close();
              }, 1000);
            }
          } catch (parseError) {
            console.error("解析消息错误:", parseError);
            console.log("原始消息:", event.data);
          }
        });

        ws.addEventListener("close", () => {
          this.isLoading = false;
        });

        ws.addEventListener("error", (error) => {
          console.error("WebSocket error:", error);
          this.updateAssistantMessage("抱歉，连接出现错误，请重试。");
          this.isLoading = false;
        });

      } catch (error) {
        console.error("Error:", error);
        this.updateAssistantMessage("抱歉，发送消息时出现错误，请重试。");
        this.isLoading = false;
      }
    },

    changeModel() {
      console.log(`已切换到${this.getModelName(this.selectedModel)}`);
    },

    getModelName(modelKey) {
      const modelNames = {
        'lite': 'Spark Lite',
        'generalv3': 'Spark Pro',
        'pro-128k': 'Spark Pro-128K',
        'generalv3.5': 'Spark Max',
        'max-32k': 'Spark Max-32K',
        '4.0Ultra': 'Spark 4.0 Ultra',
        'kjwx': '科技文献大模型'
      };
      return modelNames[modelKey] || modelKey;
    },

    updateAssistantMessage(content) {
      this.chatMessages[this.chatMessages.length - 1].content = content;
    },

    parseContent(content) {
      if (this.isBase64Image(content)) {
        return `<img src="${content}" alt="Generated image" style="max-width:100%;"/>`;
      }
      return this.parseCodeBlocks(content);
    },

    isBase64Image(str) {
      return str.startsWith('data:image/');
    },

    parseCodeBlocks(content) {
      const codeBlockRegex = /```(\w+)?\s*([\s\S]*?)```/g;
      return content.replace(codeBlockRegex, (match, lang, code) => {
        const language = lang || "javascript";
        const highlightedCode = this.highlightCode(code.trim(), language);
        return `<pre><span>${language}<span><hr style='margin:10px 0;border-top: 1px solid blue;'/><code class="language-${language}">${highlightedCode}</code></pre>`;
      });
    },

    highlightCode(code, language) {
      if (language === "javascript") {
        code = code.replace(
          /"([^"]*)"|'([^']*)'/g,
          (match, p1, p2) => `<span class="string">"${p1 || p2}"</span>`
        );
        code = code.replace(
          /\b(function|let|const|var|if|else|return)\b/g,
          '<span class="keyword">$&</span>'
        );
        code = code.replace(
          /\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g,
          (match, p1) => `<span class="function">${p1}</span>(`
        );
        code = code.replace(
          /\b(console\.log)\b/g,
          '<span class="function">$&</span>'
        );
        code = code.replace(
          /\/\/.*$/gm,
          '<span class="comment">$&</span>'
        );
        code = code.replace(
          /\/\*[\s\S]*?\*\//g,
          '<span class="comment">$&</span>'
        );
        code = code.replace(
          /\b(\d+)\b/g,
          '<span class="number">$&</span>'
        );
      }
      return code;
    },

    scrollToBottom() {
      const resultsDiv = document.getElementById('results');
      if (resultsDiv) {
        resultsDiv.scrollTo({
          top: resultsDiv.scrollHeight,
          behavior: 'smooth'
        });
      }
    },

    async getWebsocketUrl(hostUrl) {
      const APPID = '86f989e0';
      const APISecret = 'YjczOWNiZTYxZWNhY2M5ZjI3OTE5YTJi';
      const APIKey = '7264913c8b3035b87979668da32f762a';

      const host = new URL(hostUrl).host;
      const pathname = new URL(hostUrl).pathname;
      let apiKeyName = "api_key";
      let date = new Date().toGMTString();
      let algorithm = "hmac-sha256";
      let headers = "host date request-line";

      let signatureOrigin = `host: ${host}\ndate: ${date}\nGET ${pathname} HTTP/1.1`;

      try {
        let signature = await this.signatureToHmacSHA256ToBase64(signatureOrigin, APISecret);
        let authorizationOrigin = `${apiKeyName}="${APIKey}", algorithm="${algorithm}", headers="${headers}", signature="${signature}"`;
        let authorization = btoa(authorizationOrigin);

        let url = `${hostUrl}?authorization=${authorization}&date=${encodeURI(date)}&host=${host}`;
        return url;
      } catch (error) {
        console.error("生成签名出错:", error);
        throw error;
      }
    },

    async signatureToHmacSHA256ToBase64(origin, secret) {
      const encoder = new TextEncoder();
      const data = encoder.encode(origin);
      const key = encoder.encode(secret);

      try {
        const importedKey = await window.crypto.subtle.importKey(
          "raw",
          key,
          { name: "HMAC", hash: "SHA-256" },
          false,
          ["sign"]
        );

        const signatureArrayBuffer = await window.crypto.subtle.sign("HMAC", importedKey, data);

        const bytes = new Uint8Array(signatureArrayBuffer);
        let result = '';
        for (const byte of bytes) {
          result += String.fromCharCode(byte);
        }
        return btoa(result);
      } catch (error) {
        console.error("计算HMAC-SHA256签名出错:", error);
        throw error;
      }
    },

    getParams(textList) {
      let functions = this.getFunctions();
      let modelConfig = this.models[this.selectedModel];

      let params = {
        "header": {
          "app_id": '86f989e0',
          "uid": 'red润'
        },
        "parameter": {
          "chat": {
            "domain": modelConfig.domain,
            "temperature": 0.5,
            "max_tokens": modelConfig.maxTokens,
          }
        },
        "payload": {
          "message": {
            "text": textList
          },
          "functions": {
            "text": functions
          }
        }
      };

      return params;
    },

    getFunctions() {
      return [
        this.weatherFunction,
        this.baiduQuestions,
        this.imgQuestions
      ];
    },

    getFunctionByName(name) {
      const functions = this.getFunctions();
      return functions.find(func => func.name === name);
    },

    // 修复：将对象定义改为函数定义
    weatherFunction(name, params) {
      console.log("天气查询函数被调用", name, params);
      let location = params.location;
      if (location == "北京") {
        window.open("https://weather.cma.cn/web/weather/54511.html");
      } else if (location == "山东") {
