    sendToTranscribe(audioBlob) {
      console.log("发送语音转写请求...");
      const formData = new FormData();
      const file = new File([audioBlob], "recording.wav", { type: "audio/wav" });
      formData.append("file", file);

      axios.post(
        "https://117.72.49.76:443/api/transcribe",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      )
        .then(response => {
          if (response.data.status === "success") {
            this.transcriptionResult = response.data.text;
            this.$message({
              message: '语音转写成功',
              type: 'success'
            });
            console.log("语音转写成功");

            // 将转写结果添加到聊天输入
            this.userInput = this.transcriptionResult;
          } else {
            this.transcriptionResult = "转写失败，请重试";
            this.$message({
              message: '语音转写失败',
              type: 'error'
            });
            console.error("语音转写失败");
          }
        })
        .catch(error => {
          console.error("网络错误:", error);
          this.transcriptionResult = "网络请求失败";
          this.$message({
            message: '网络错误，转写失败',
            type: 'error'
          });
        });
    },

    // 语音分析方法
    initVoiceAnalysis() {
      this.audioContext = null;
      this.analyser = null;
      this.microphone = null;
      this.scriptProcessor = null;
      this.animationFrameId = null;
      this.pitchHistory = [];
      console.log("语音分析初始化完成");
    },

    startVoiceAnalysis() {
      console.log("启动语音分析...");
      if (!this.audioContext) {
        this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      }

      navigator.mediaDevices.getUserMedia({ audio: true, video: false })
        .then(stream => {
          this.microphone = this.audioContext.createMediaStreamSource(stream);
          this.analyser = this.audioContext.createAnalyser();
          this.analyser.fftSize = 2048;
          this.analyser.smoothingTimeConstant = 0.8;

          this.scriptProcessor = this.audioContext.createScriptProcessor(4096, 1, 1);

          this.microphone.connect(this.analyser);
          this.analyser.connect(this.scriptProcessor);
          this.scriptProcessor.connect(this.audioContext.destination);

          this.scriptProcessor.onaudioprocess = (event) => {
            this.processAudio(event);
          };

          this.initFrequencyChart();
          this.startAnimation();

          this.isAnalyzing = true;
          console.log("语音分析启动成功");
        })
        .catch(error => {
          console.error('语音分析启动失败:', error);
          alert('语音分析启动失败，请确保已授予麦克风权限。');
        });
    },

    stopVoiceAnalysis() {
      console.log("停止语音分析...");
      this.isAnalyzing = false;

      if (this.animationFrameId) {
        cancelAnimationFrame(this.animationFrameId);
      }

      if (this.microphone) {
        this.microphone.disconnect();
      }
      if (this.analyser) {
        this.analyser.disconnect();
      }
      if (this.scriptProcessor) {
        this.scriptProcessor.disconnect();
        this.scriptProcessor.onaudioprocess = null;
      }

      if (this.audioContext) {
        this.audioContext.close();
        this.audioContext = null;
      }
      console.log("语音分析停止");
    },

    processAudio(event) {
      const inputBuffer = event.inputBuffer.getChannelData(0);

      // 计算音量 (RMS)
      let sum = 0;
      for (let i = 0; i < inputBuffer.length; i++) {
        sum += inputBuffer[i] * inputBuffer[i];
      }
      const rms = Math.sqrt(sum / inputBuffer.length);
      this.volume = 20 * Math.log10(rms) || -100; // dB

      // 计算音量百分比 (0-100)
      this.volumePercent = Math.min(100, Math.max(0, (this.volume + 100) * 100 / 100));

      // 获取浮点频率数据
      this.analyser.getFloatFrequencyData(this.frequencyData);

      // 计算音高
      let maxAmp = -Infinity;
      let maxFreq = 0;

      for (let i = 0; i < this.frequencyData.length; i++) {
        if (this.frequencyData[i] > maxAmp) {
          maxAmp = this.frequencyData[i];
          maxFreq = i * (this.audioContext.sampleRate / 2) / this.frequencyData.length;
        }
      }

      // 过滤低振幅噪声
      if (maxAmp > -90) {
        this.pitch = maxFreq;

        // 更新音调历史，用于计算稳定性
        this.pitchHistory.push(maxFreq);
        if (this.pitchHistory.length > 20) {
          this.pitchHistory.shift();
        }

        // 计算音调稳定性 (0-100%)
        if (this.pitchHistory.length > 5) {
          const avgPitch = this.pitchHistory.reduce((a, b) => a + b, 0) / this.pitchHistory.length;
          let variance = 0;

          this.pitchHistory.forEach(freq => {
            variance += Math.pow(freq - avgPitch, 2);
          });

          const stdDev = Math.sqrt(variance / this.pitchHistory.length);
          this.pitchStability = Math.max(0, Math.min(100, 100 - (stdDev / 50) * 100));
        }
      }

      // 计算音调位置 (0-100%) 用于显示
      this.pitchPosition = Math.min(100, Math.max(0, this.pitch / 1500 * 100));
    },

    initFrequencyChart() {
      this.canvas = this.$refs.frequencyCanvas;
      this.canvasCtx = this.canvas.getContext('2d');

      const resizeCanvas = () => {
        this.canvas.width = this.canvas.offsetWidth;
        this.canvas.height = this.canvas.offsetHeight;
      };

      resizeCanvas();
      window.addEventListener('resize', resizeCanvas);
      console.log("频率图表初始化完成");
    },

    updateFrequencyChart() {
      if (!this.canvasCtx) return;

      const canvas = this.canvas;
      const ctx = this.canvasCtx;
      const width = canvas.width;
      const height = canvas.height;

      ctx.clearRect(0, 0, width, height);

      this.analyser.getByteFrequencyData(this.byteFrequencyData);

      const barWidth = width / this.byteFrequencyData.length * 2.5;
      let x = 0;

      for (let i = 0; i < this.byteFrequencyData.length; i++) {
        const barHeight = (this.byteFrequencyData[i] / 255) * height;

        const hue = (i / this.byteFrequencyData.length) * 240;
        ctx.fillStyle = `hsl(${hue}, 100%, 50%)`;

        ctx.fillRect(x, height - barHeight / 2, barWidth, barHeight / 2);

        x += barWidth + 1;
      }
    },

    startAnimation() {
      const animate = () => {
        this.updateFrequencyChart();
        this.animationFrameId = requestAnimationFrame(animate);
      };

      animate();
      console.log("频率图表动画启动");
    },

    // 摄像头和表情识别方法
    initCamera() {
      console.log("初始化摄像头...");
      navigator.mediaDevices.getUserMedia({ video: true })
        .then(stream => {
          this.mediaStream = stream;
          this.$refs.video.srcObject = stream;
          console.log("摄像头初始化成功");
        })
        .catch(err => {
          console.error("摄像头访问失败:", err);
          alert('无法访问摄像头，请确保已授予权限');
        });
    }
  }
};
